const $=s=>document.querySelector(s), root=$('#app');let me=null,view='trips',selected=null,cat=null,tripPage=0,poll=null,watch=null,tracking=null,sending=false,seenNotice=null,toastTimer=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
const hours=v=>Number(v||0).toFixed(1)+' h';
const duration=v=>{if(v==null||!Number.isFinite(Number(v)))return '—';const sec=Math.max(0,Math.floor(Number(v))),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h+'h '+String(m).padStart(2,'0')+'min '+String(s).padStart(2,'0')+'s'};
