function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500)}
async function apiRaw(path,body,method='POST'){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),20000);try{const opt={credentials:'same-origin',cache:'no-store',headers:{'X-MOZ-Request':'1'}};if(body!==undefined){opt.method=method;if(body instanceof FormData)opt.body=body;else{opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}}opt.signal=controller.signal;const r=await fetch('/api'+path,opt);if(!r.ok){let j;try{j=await r.json()}catch{}const e=new Error(j?.error||({401:'Sessão inválida ou credenciais incorretas.',403:'Acesso não autorizado.',404:'Registro não encontrado.',409:'Registro em conflito. Atualize e tente novamente.',429:'Muitas tentativas. Aguarde.'}[r.status]||'Falha na comunicação.'));e.status=r.status;throw e}const raw=await r.text();if(!raw.trim())return null;try{return JSON.parse(raw)}catch{throw new Error('O servidor retornou uma resposta inesperada. Tente novamente.')} }catch(e){if(e.name==='AbortError')throw new Error('O servidor demorou para responder. Tente novamente.');if(e instanceof TypeError)throw new Error('Não foi possível conectar ao MOZ. Verifique sua conexão.');throw e}finally{clearTimeout(timer)}}
const OFFLINE_CACHE='moz-driver-offline-v1';
function offlineRead(){try{return JSON.parse(localStorage.getItem(OFFLINE_CACHE)||'null')}catch{return null}}
function offlineWrite(value){try{localStorage.setItem(OFFLINE_CACHE,JSON.stringify(value))}catch{}}
function offlineClear(){try{localStorage.removeItem(OFFLINE_CACHE)}catch{}}
function offlineKey(path){return path==='/driver/tracking'||/^\/trips\?page=\d+$/.test(path)||/^\/trips\/[0-9a-f-]{36}$/i.test(path);}
function offlineStore(path,value){let c=offlineRead();if(path==='/me'||path==='/login'){if(value?.role==='driver'&&value.identityVerified){if(c?.user?.id!==value.id)c={user:value,data:{}};c.user=value;offlineWrite(c);}else offlineClear();return;}
 if(me?.role!=='driver'||c?.user?.id!==me.id||!offlineKey(path))return;
 if(path.startsWith('/trips/')&&value?.trip){value={...value,events:(value.events||[]).slice(-50),pods:(value.pods||[]).slice(-30)};}
 c.data[path]=value;offlineWrite(c);}
async function api(path,body,method='POST'){try{
 if(body===undefined&&!navigator.onLine)throw new Error('Sem conexão.');
 const r=await apiRaw(path,body,method);if(body===undefined||path==='/login')offlineStore(path,r);return r;
 }catch(e){if(body!==undefined)throw e;if(e.status===401||e.status===403){if(path==='/me')offlineClear();throw e;}
 if(e.status&&e.status!==503)throw e;const c=offlineRead();if(path==='/me'&&c?.user?.role==='driver')return c.user;
 if(me?.role==='driver'&&c?.user?.id===me.id&&offlineKey(path)&&Object.prototype.hasOwnProperty.call(c.data,path))return c.data[path];throw e;}}
const panel=(title,body)=>'<section class="panel"><h2>'+esc(title)+'</h2>'+body+'</section>';
const field=(n,label,type='text',extra='')=>'<label>'+esc(label)+'<input name="'+n+'" type="'+type+'" '+extra+'></label>';
const select=(n,label,opts,extra='')=>'<label>'+esc(label)+'<select name="'+n+'" '+extra+'>'+opts.map(x=>'<option value="'+esc(x[0])+'">'+esc(x[1])+'</option>').join('')+'</select></label>';
const checkbox=(n,label)=>'<label><input type="checkbox" name="'+n+'">'+esc(label)+'</label>';
const submit=t=>'<button class="primary" type="submit">'+esc(t)+'</button>';
const btn=(t,id,cls='')=>'<button type="button" id="'+id+'" class="'+cls+'">'+esc(t)+'</button>';
const form=(id,content,button)=>'<form id="'+id+'">'+content+submit(button)+'</form>';
const data=f=>Object.fromEntries(new FormData(f));
const n=(x,k,def)=>Number(x[k]||def);
function wire(id,fn){const f=document.getElementById(id);if(f)f.addEventListener('submit',async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');if(b.disabled)return;const old=b.textContent, status=f.querySelector('.form-feedback');b.disabled=true;b.textContent=id==='auth'?'Aguarde…':'Salvando…';f.setAttribute('aria-busy','true');if(status){status.hidden=true;status.textContent=''}try{await fn(data(f),f)}catch(err){if(status){status.textContent=err.message||'Não foi possível concluir o acesso.';status.hidden=false;status.focus()}else toast(err.message)}finally{b.disabled=false;b.textContent=old;f.removeAttribute('aria-busy')}})}
function on(id,fn){const e=document.getElementById(id);if(e)e.onclick=async()=>{try{await fn()}catch(err){toast(err.message)}}}
function login(register=false){stopGps(true);offlineClear();me=null;root.dataset.mode='auth';$('#session').hidden=true;root.innerHTML='<div class="auth-shell"><aside class="auth-visual" aria-label="MOZ"><div class="auth-mark">MOZ<span>.</span></div><p>Gestão logística</p><div class="auth-rule"></div><dl><dt>Operações</dt><dd>Viagens e etapas</dd><dt>Monitoramento</dt><dd>Localização e eventos</dd><dt>Entregas</dt><dd>Comprovantes e histórico</dd></dl></aside><section class="auth-form"><div class="login">'+panel(register?'Cadastro gratuito de motorista':'Entrar no MOZ',register?form('auth',field('name','Nome completo','text','required maxlength="160" autocomplete="name"')+field('cpf','CPF','text','required inputmode="numeric"')+field('phone','Celular com DDD','tel','required autocomplete="tel"')+field('password','Crie uma senha de pelo menos 10 caracteres','password','required minlength="10" autocomplete="new-password"'),'Criar conta')+'<p>A identidade será conferida antes da liberação das viagens.</p>'+btn('Já tenho conta','switch') :form('auth',field('login','E-mail ou CPF','text','required autocomplete="username"')+field('password','Senha','password','required autocomplete="current-password"'),'Entrar')+btn('Sou motorista — criar conta gratuita','switch'))+'<p class="auth-note">Acesso de operador, cliente autorizado ou motorista.</p></div></section></div>';
 const feedback=document.createElement('div');feedback.className='form-feedback';feedback.setAttribute('role','alert');feedback.tabIndex=-1;feedback.hidden=true;$('#auth').append(feedback);wire('auth',async x=>{if(register){const r=await api('/register-driver',x);login();toast(r?.message||'Cadastro recebido.');return}const user=await api('/login',x);if(!user?.id||!user?.role)throw new Error('Não foi possível confirmar a sessão.');me=user;try{await enter()}catch(e){if(!root.querySelector('#auth')){login();const f=root.querySelector('.form-feedback');f.textContent='A sessão foi recebida, mas não foi possível abrir a operação: '+e.message;f.hidden=false;f.focus()}else throw e}});on('switch',()=>login(!register))}
let live=null,liveTimer=null;
let liveBusy=false,livePending=false,lastLiveRefresh=0;
function scheduleLive(){livePending=true;if(liveBusy||liveTimer)return;const delay=Math.max(0,3000-(Date.now()-lastLiveRefresh));liveTimer=setTimeout(()=>{liveTimer=null;runLiveRefresh()},delay);}
async function runLiveRefresh(){
 if(liveBusy||!livePending)return;livePending=false;liveBusy=true;lastLiveRefresh=Date.now();const owner=me?.id;
 try{if(!me||!navigator.onLine)return;await notices(view==='notices').catch(()=>{});if(me?.id===owner&&view==='trips'&&!selected&&$('#tripRows'))await trips(true);else if(me?.id===owner&&view==='macro'&&$('#fleetMap'))await macro(true);}catch{}finally{liveBusy=false;if(livePending)scheduleLive()}
}
async function startLive(){if(!window.signalR||!me)return;if(live)await live.stop().catch(()=>{});live=new signalR.HubConnectionBuilder().withUrl('/hubs/events').withAutomaticReconnect().build();live.on('changed',()=>{if(me?.role==='driver')syncTracking().catch(()=>{});scheduleLive()});await live.start().catch(()=>{});}

async function enter(){if(!me)return;root.dataset.mode='workspace';root.dataset.role=me.role;$('#session').hidden=false;$('#noticeBtn').hidden=me.role==='global';$('#who').textContent=me.name+' · '+({global:'Administração',operator:'Operador',client:'Cliente',driver:'Motorista'}[me.role]||'');view=me.role==='global'?'global':me.role==='driver'?'trips':'macro';selected=null;tripPage=0;tripSearch='';tripStatus='';tripClient='';seenNotice=null;noticePage=0;lastLiveRefresh=0;sidebarCollapsed=readSidebar();await render();clearInterval(poll);poll=setInterval(async()=>{if(!me)return;try{if(me.role==='driver'&&!me.identityVerified){const current=await api('/me');if(current.identityVerified){me=current;await render()}}await syncTracking();await flush();if(navigator.onLine)scheduleLive();await flush()}catch{}},5000);await syncTracking();await flush();if(navigator.onLine){await notices(false).catch(()=>{});await startLive()}}
