async function render(){if(!me)return;if(window.MozMaps)MozMaps.clear();root.innerHTML='<div class="workspace"><aside class="side"><div class="sidebar-heading"><div class="side-label">Navegação</div><button type="button" id="sidebarToggle" aria-controls="sidebarNav" aria-expanded="true" aria-label="Recolher menu lateral" title="Recolher menu lateral">'+sidebarIcon('toggle')+'</button></div>'+nav()+'</aside><section class="main-area"><div class="page-heading"><div class="eyebrow">'+esc({global:'ADMINISTRAÇÃO',operator:'OPERAÇÕES',client:'ACOMPANHAMENTO',driver:'MOTORISTA'}[me.role])+'</div><h1>'+esc({global:'Operadores',drivers:'Conferência de motoristas',catalog:'Cadastros',new:'Programar viagem',report:'Indicadores',notices:'Notificações',detail:'Detalhes da viagem',macro:'Visão macro',trips:me.role==='driver'?'Minhas viagens':'Tracking de viagens'}[view]||'Operação')+'</h1></div><div id="content"></div></section></div>';bindSidebar(root.querySelector('.workspace'));for(const [id,v] of Object.entries({navGlobal:'global',navDrivers:'drivers',navMacro:'macro',navTrips:'trips',navNew:'new',navCat:'catalog',navReport:'report'})){const button=document.getElementById(id);if(button&&view===v){button.classList.add('active');button.setAttribute('aria-current','page')}on(id,async()=>{view=v;selected=null;await render()})}try{if(view==='global')await global();else if(view==='drivers')await drivers();else if(view==='catalog')await catalog();else if(view==='new')await newTrip();else if(view==='report')await report();else if(view==='notices')await notices(true);else if(view==='detail')await detail();else if(view==='macro'&&me.role!=='driver')await macro();else await trips()}catch(e){$('#content').innerHTML=panel('Não foi possível carregar','<p>'+esc(e.message)+'</p>');if(e.status===401)login()}}
