function trackingCards(r){
 if(!r)return '';
 return '<dl class="macro-metrics tracking-metrics">'+[['Programadas',r.scheduled,'pending'],['Em operação',r.active,'active'],['Finalizadas',r.finalized,'done'],['Canceladas',r.cancelled,'cancel']].map(([k,v,state])=>'<div class="macro-metric" data-metric="'+state+'"><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><p class="tracking-count-note">Indicadores de todas as viagens '+(tripClient?'do cliente selecionado':'do seu escopo')+', independentemente da busca, status e página da grade.</p>';
}
function changeHtml(el,html){if(el&&el.innerHTML!==html)el.innerHTML=html;}
function patchTripRows(container,html){
 const draft=document.createElement('template');draft.innerHTML=html;
 // The container holds either a driver list or the table and its scroll wrapper.
 const current=container.querySelector('tbody')||container.querySelector('.driver-list');
 const incoming=draft.content.querySelector('tbody')||draft.content.querySelector('.driver-list');
 if(!current||!incoming){changeHtml(container,html);return;}
 const keyed=new Map([...current.children].map(el=>[el.dataset.tripRow,el]));
 let cursor=current.firstElementChild;
 for(const next of [...incoming.children]){
  let row=keyed.get(next.dataset.tripRow);if(row){keyed.delete(next.dataset.tripRow);
   if(row.tagName==='TR'){for(let i=0;i<next.cells.length;i++){const cell=row.cells[i],fresh=next.cells[i];if(cell&&cell.innerHTML!==fresh.innerHTML){if(!cell.contains(document.activeElement))cell.innerHTML=fresh.innerHTML;}}}
   else if(row.innerHTML!==next.innerHTML&&!row.contains(document.activeElement))row.innerHTML=next.innerHTML;
  }else row=next;
  if(row!==cursor)current.insertBefore(row,cursor);cursor=row.nextElementSibling;
 }
 for(const row of keyed.values())row.remove();
}
function canActivateTrip(t,role){return role==='operator'&&t.status==='Programada'&&!t.finished&&!t.trackingActive&&!t.started;}
function activationButton(t,role){return canActivateTrip(t,role)?'<button type="button" class="primary activate-trip" data-activate-trip="'+esc(t.id)+'" aria-label="Ativar viagem '+esc(tripRef(t))+'">ATIVAR VIAGEM</button>':'';}
const activatingTrips=new Set();
function bindActivationButtons(scope,after){
 scope?.querySelectorAll('[data-activate-trip]').forEach(button=>{button.onclick=async()=>{
 const id=button.dataset.activateTrip,owner=me?.id;if(me?.role!=='operator'||activatingTrips.has(id))return;
 activatingTrips.add(id);const old=button.textContent;const peers=()=>[...scope.querySelectorAll('[data-activate-trip]')].filter(b=>b.dataset.activateTrip===id);
 for(const b of peers()){b.disabled=true;b.textContent='Ativando…';}
 try{await api('/trips/'+encodeURIComponent(id)+'/action',{action:'activate',message:null});
 if(me?.id!==owner)return;button.blur();toast('Viagem ativada. Rastreamento autorizado.');
 try{await after(id)}catch(e){toast('Viagem ativada. Atualize a tela para consultar o novo estado.')}
 }catch(e){if(me?.id===owner)toast(e.message)}
 finally{activatingTrips.delete(id);for(const b of peers()){b.disabled=false;b.textContent=old;}}
 };});
}
function bindTripButtons(){const scope=$('#tripRows');scope?.querySelectorAll('[data-trip]').forEach(b=>b.onclick=async()=>{detailReturn='trips';selected=b.dataset.trip;view='detail';await render()});bindActivationButtons(scope,async()=>{if(view==='trips')await trips(true)});}

function patchSelect(id,html){const el=document.getElementById(id);if(!el||document.activeElement===el)return;const next=document.createElement('template');next.innerHTML=html;const fresh=next.content.querySelector('#'+id);if(!fresh)return;const currentValue=el.value;const sig=s=>[...s.options].map(o=>o.value+'|'+o.text).join('\n');if(sig(el)!==sig(fresh)){el.replaceChildren(...fresh.options);if([...el.options].some(o=>o.value===currentValue))el.value=currentValue;else el.value=fresh.value;}}

