 '<section class="detail-view" data-detail-view="proof" hidden>'+panel('Comprovantes da viagem',proofGallery(d))+'</section>'+
 '<section class="detail-view" data-detail-view="management" hidden>'+operatorControls(t)+panel('Etapas registradas',detailStages(d,a))+'</section>';
