const dbPromise=new Promise((resolve,reject)=>{const q=indexedDB.open('moz-local',1);q.onupgradeneeded=()=>q.result.createObjectStore('queue',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});
