const queue=item=>tx('readwrite',s=>s.put(item));const remove=id=>tx('readwrite',s=>s.delete(id));const getQueue=()=>tx('readonly',s=>s.getAll());
async function flush(){if(sending||!me||me.role!=='driver'||!navigator.onLine)return;sending=true;const owner=me.id;try{
 const items=(await getQueue()).filter(q=>q.user===owner&&q.state!=='review').sort((a,b)=>new Date(a.fix?.at||a.captured)-new Date(b.fix?.at||b.captured));
 for(let i=0;i<items.length&&me?.id===owner;){const item=items[i];try{
 if(item.type==='fix'){const batch=[item];while(batch.length<100&&items[i+batch.length]?.type==='fix'&&items[i+batch.length].trip===item.trip)batch.push(items[i+batch.length]);const r=await api('/trips/'+item.trip+'/fixes',batch.map(x=>x.fix));const ids=[...(r.acceptedIds||[]),...(r.discardIds||[])];for(const q of batch)if(ids.includes(q.id))await remove(q.id);if(r.trackingActive===false&&tracking===item.trip)stopGps();if(ids.length<batch.length)break;i+=batch.length;}
 else{const f=new FormData();f.append('id',item.id);f.append('captured',item.captured);if(item.stageId)f.append('stageId',item.stageId);f.append('file',item.file);const r=await api('/trips/'+item.trip+'/pod',f);if(item.finish&&r.status!=='Finalizada'){await queue({...item,state:'review'});toast('Comprovante recebido; encerramento requer conferência.');}else{await remove(item.id);toast('Comprovante sincronizado.');}if(r.status==='Finalizada'&&tracking===item.trip)stopGps();i++;}
 }catch(e){if(item.type==='pod'&&(e.status===400||e.status===404)){await queue({...item,state:'review'});toast('Comprovante preservado no aparelho; '+e.message);i++;continue;}break;}
 }
 }finally{sending=false}}
let noticePage=0;
async function notices(show){if(!me||me.role==='global')return;const owner=me.id;const r=await api('/notices?page=0');if(me?.id!==owner)return;$('#count').textContent=r.unread;const newest=r.items[0];if(seenNotice!==null&&newest&&newest.id!==seenNotice){const idx=r.items.findIndex(e=>e.id===seenNotice);const fresh=(idx>=0?r.items.slice(0,idx):r.items).filter(e=>!e.read);if(fresh.length)toast(fresh.length===1?tripRef(fresh[0])+' · '+fresh[0].message:fresh.length+' novas atualizações operacionais. Consulte as notificações.');}seenNotice=newest?.id||'';if(!show)return;const page=noticePage===0?r:await api('/notices?page='+noticePage);if(me?.id!==owner||view!=='notices')return;const noticeHtml=panel('Notificações','<div class="row">'+btn('Ativar notificações no dispositivo','pushOn')+btn('Desativar neste dispositivo','pushOff')+'</div><p>'+r.unread+' não lida(s) · Página '+(noticePage+1)+'</p>'+(page.items.length?page.items.map(e=>'<div class="trip"><div><strong>'+esc(e.kind)+(e.read?'':' · NOVA')+'</strong><p>'+esc(e.message)+'</p><small>Código da viagem: '+esc(tripRef(e))+' · '+date(e.at)+'</small></div><button data-event="'+esc(e.id)+'" data-target="'+esc(e.tripId)+'">Abrir viagem</button></div>').join(''):'<p>Sem notificações.</p>')+'<div class="row pager">'+btn('Página anterior','noticePrev')+btn('Próxima página','noticeNext')+'</div>');const current=$('#content');if(current.dataset.noticeHtml===noticeHtml&&current.querySelector('#noticePrev'))return;current.dataset.noticeHtml=noticeHtml;content(noticeHtml);on('pushOn',enablePush);on('pushOff',()=>disablePush(true));$('#noticePrev').disabled=noticePage===0;$('#noticeNext').disabled=(noticePage+1)*100>=page.total;on('noticePrev',async()=>{noticePage--;await notices(true)});on('noticeNext',async()=>{noticePage++;await notices(true)});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=async()=>{try{await api('/notices/'+b.dataset.event+'/read',{});detailReturn='trips';selected=b.dataset.target;view='detail';await render();await notices(false)}catch(e){toast(e.message)}})}
async function report(){const r=await api('/reports');content(panel('Indicadores consolidados','<div class="grid">'+[['Viagens',r.total],['Programadas',r.scheduled],['Em operação',r.active],['Finalizadas',r.finalized],['Distância registrada',num(r.distanceKm)+' km'],['Em movimento',hours(r.movingHours)],['Parado',hours(r.idleHours)]].map(([k,v])=>'<div class="stat"><small>'+esc(k)+'</small><strong>'+esc(v)+'</strong></div>').join('')+'</div>'+'<div class="grid"><label>Programadas a partir de<input id="reportFrom" type="date"></label><label>Programadas até<input id="reportTo" type="date"></label></div>'+btn('Exportar viagens CSV','csvReport')+btn('Imprimir relatório','printReport')));on('printReport',()=>window.print());on('csvReport',async()=>{try{const p=new URLSearchParams();const from=document.getElementById('reportFrom').value,to=document.getElementById('reportTo').value;if(from)p.set('from',new Date(from+'T00:00:00').toISOString());if(to){const end=new Date(to+'T00:00:00');end.setDate(end.getDate()+1);p.set('to',end.toISOString())}if(from&&to&&from>to)throw new Error('Período inválido.');const r=await fetch('/api/reports/trips.csv?'+p,{credentials:'same-origin',cache:'no-store',headers:{'X-MOZ-Request':'1'}});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||'Não foi possível exportar.')}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='moz-viagens.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){alert(e.message)}})}
$('#logout').onclick=async()=>{try{await disablePush(false).catch(()=>{});await api('/logout',{});if(live)await live.stop().catch(()=>{});stopGps(true);clearInterval(poll);login()}catch(e){toast(e.message)}};
$('#noticeBtn').onclick=async()=>{if(!me||me.role==='global')return;view='notices';noticePage=0;await render()};
window.addEventListener('online',()=>{syncTracking().catch(()=>{});flush().catch(()=>{});if(me&&!live)startLive().catch(()=>{})});window.addEventListener('offline',()=>{if(tracking)toast('Sem internet. A viagem ativada continua com armazenamento local.');});window.addEventListener('visibilitychange',()=>{if(document.hidden&&tracking&&!window.MozNative)toast('O GPS web pode ser interrompido em segundo plano.');if(!document.hidden){syncTracking().catch(()=>{});flush().catch(()=>{})}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js?v=17',{updateViaCache:'none'}).catch(()=>{});
(async()=>{if(location.protocol!=='https:'){root.innerHTML='<div class="auth-shell"><section class="auth-visual"><div class="auth-mark">MOZ<span>.</span></div><p>Gestão logística</p></section><section class="auth-form"><div class="login"><h2>Conexão segura necessária</h2><p>Por segurança, o acesso às operações exige HTTPS. Não informe credenciais em conexão não criptografada.</p><a href="https://moz.runasp.net/">Acessar conexão segura</a></div></section></div>';return}try{me=await api('/me');await enter()}catch{login()}})();

function keyBytes(key){const s=key.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(key.length/4)*4,'=');return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw new Error('Notificações push não são suportadas neste dispositivo ou navegador.');if(await Notification.requestPermission()!=='granted')throw new Error('Permissão de notificações não concedida.');const r=await navigator.serviceWorker.ready;const k=await api('/push/key');const sub=await r.pushManager.getSubscription()||await r.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(k.publicKey)});const d=sub.toJSON();await api('/push/subscribe',{endpoint:d.endpoint,p256dh:d.keys.p256dh,auth:d.keys.auth,kinds:null});toast('Notificações ativadas neste dispositivo.')}
async function disablePush(show){if(!('serviceWorker'in navigator)||!('PushManager'in window))return;const r=await navigator.serviceWorker.getRegistration();const sub=await r?.pushManager.getSubscription();if(sub){await api('/push/unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe()}if(show)toast('Notificações desativadas neste dispositivo.')}
